namespace Milvasoft.BulkExtensions;

/// <summary>
/// Options for a single bulk operation.
/// </summary>
/// <remarks>
/// Property names are the names used in the entity model. Properties of owned or complex types are written as a dotted path
/// such as <c>ShippingAddress.City</c>. Giving only the navigation or complex property name (<c>ShippingAddress</c>) selects all of its properties.
/// Names that do not exist in the model cause an <see cref="ArgumentException"/>.
/// </remarks>
public sealed class BulkConfig
{
    /// <summary>
    /// When <see langword="true"/>, values generated by the database are written back to the entities after the operation.
    /// For inserts these are identity keys, default values and computed columns. For updates and upserts these are values
    /// generated on update, such as computed columns and the PostgreSQL <c>xmin</c> row version.
    /// Ignored by delete and read operations. Default is <see langword="false"/>.
    /// </summary>
    public bool SetOutputIdentity { get; set; }

    /// <summary>
    /// When set, only these properties are inserted or updated. Key and match properties that the operation needs are always used.
    /// </summary>
    public List<string> PropertiesToInclude { get; set; }

    /// <summary>
    /// Properties that are not inserted or updated.
    /// </summary>
    public List<string> PropertiesToExclude { get; set; }

    /// <summary>
    /// Properties used to match input entities to existing rows in update, upsert, delete and read operations.
    /// When not set, the primary key is used. For upserts these properties must have a unique constraint or unique index.
    /// A NULL match value matches no row.
    /// </summary>
    public List<string> UpdateByProperties { get; set; }

    /// <summary>
    /// Only for <c>BulkInsertOrUpdate</c>: when set, only these properties are updated on rows that already exist.
    /// An empty list means existing rows are left unchanged and only new rows are inserted.
    /// Properties left at their CLR default that have a database default are never updated on existing rows.
    /// </summary>
    public List<string> PropertiesToIncludeOnUpdate { get; set; }

    /// <summary>
    /// Only for <c>BulkInsertOrUpdate</c>: properties that are not updated on rows that already exist.
    /// </summary>
    public List<string> PropertiesToExcludeOnUpdate { get; set; }

    /// <summary>
    /// Command timeout in seconds. When not set, the timeout of the <see cref="Microsoft.EntityFrameworkCore.DbContext"/> is used.
    /// </summary>
    public int? CommandTimeout { get; set; }
}